'use strict';
const $ = (s, root = document) => root.querySelector(s);
const tg = window.Telegram?.WebApp;
const preview = new URLSearchParams(location.search).get('preview') === '1';
const state = {data:null, people:null, admin:null, report:null, reportError:'', notifications:{items:[],unread:0}, view:'overview', login:null, period:'today', kind:'trades', offset:0, from:'', to:'', busy:false, currency:null};
let generation = 0, refreshTimer, toastTimer, notificationsStarted = false, lastNotificationId = 0;
const paths = {overview:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',accounts:'M3 7h18v14H3z M3 7V4h14v3 M16 12h5v5h-5z',deals:'M4 5h16 M4 12h16 M4 19h16 M8 2v6 M16 9v6 M9 16v6',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 3a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',up:'M7 17 17 7 M7 7h10v10',down:'M7 7l10 10 M7 17h10V7',refresh:'M20 7A8 8 0 0 0 6 5L3 8 M3 3v5h5 M4 17a8 8 0 0 0 14 2l3-3 M21 21v-5h-5',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',chevron:'M9 5l7 7-7 7',chart:'M3 19h18 M4 15l5-5 5 3 6-9',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',back:'M19 12H5 M10 7l-5 5 5 5',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',copy:'M8 8h13v13H8z M16 8V3H3v13h5'};
paths.bell='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4';
Object.assign(paths,{
 overview:'M4 10.5 12 4l8 6.5V19a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2z M9 21v-7h6v7',
 accounts:'M4 6h15a2 2 0 0 1 2 2v12H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h13 M16 12h5v5h-5a2 2 0 0 1 0-5z',
 deals:'M4 19h16 M7 16V9 M12 16V5 M17 16v-5 M5 9h4 M10 5h4 M15 11h4',
 people:'M8.5 11a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7z M2 20v-2a5 5 0 0 1 5-5h3a5 5 0 0 1 5 5v2z M17 4a3.5 3.5 0 0 1 0 7 M18 13a4 4 0 0 1 4 4v3',
 settings:'M4 6h16 M4 12h16 M4 18h16 M9 4v4 M16 10v4 M9 16v4',
 chart:'M3 20h18 M5 16l5-5 4 3 5-7 M16 7h3v3',
 refresh:'M20 8a8 8 0 0 0-14-3L3 8 M3 3v5h5 M4 16a8 8 0 0 0 14 3l3-3 M21 21v-5h-5',
 bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4'
});
function icon(name, cls=''){return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.chart}"/></svg>`;}
function esc(value){return String(value??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(value, cur='USD', signed=false){if(value==null||!Number.isFinite(Number(value)))return '—';return new Intl.NumberFormat('ru-RU',{style:'currency',currency:cur||'USD',maximumFractionDigits:2,signDisplay:signed?'exceptZero':'auto'}).format(value);}
function number(value){return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(value||0);}
function percent(value){return `${value>=0?'+':''}${new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:3}).format(value)}%`;}
function date(value, full=false){const raw=String(value||'');const iso=raw.length===10?raw+'T00:00:00Z':/(Z|[+-]\d{2}:\d{2})$/.test(raw)?raw:raw+'Z';return new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'short',...(full?{hour:'2-digit',minute:'2-digit',timeZone:'UTC'}:{})}).format(new Date(iso));}
function signedClass(value){return value<0?'negative':'positive';}
function notice(text, warning=false){return `<div class="notice ${warning?'warning':''}">${esc(text)}</div>`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function button(action,text,style='secondary',ico='',attrs=''){return `<button class="button ${style}" data-action="${action}" ${attrs}>${ico?icon(ico):''}<span class="button-label">${esc(text)}</span></button>`;}
function broadcastPreview(text){return esc(text).replace(/&lt;(\/?)(b|i|code|blockquote)&gt;/g,'<$1$2>');}
function fileSize(bytes){return `${number(bytes/1024/1024)} МБ`;}
const tabs=[['overview','Обзор'],['accounts','Счета'],['deals','Сделки'],['people','Гости'],['settings','Настройки']];
const periods=[['today','Сегодня'],['yesterday','Вчера'],['week','Эта неделя'],['lastweek','Прошлая неделя'],['month','Этот месяц'],['lastmonth','Прошлый месяц'],['all','Всё время'],['custom','Свои даты']];
function nav(){const html=tabs.map(([id,label])=>`<a href="#${id}" aria-label="${label}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></a>`).join('');$('#desktop-nav').innerHTML=html;$('#mobile-nav').innerHTML=html;$('#crumb').textContent=tabs.find(([id])=>id===state.view)?.[1]||'Счёт';}
function header(title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">Ваш капитал в движении</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('chart')}<h2>${esc(title)}</h2><p>${esc(text)}</p>${action}</div>`;}
function notificationPanel(){const items=state.notifications?.items||[];const body=items.length?items.map(i=>`<div class="notification-item ${i.read_at?'':'unread'}"><span class="notification-dot">${icon(i.kind==='trades'?'chart':i.kind==='message'?'bell':i.kind==='deposits'?'up':i.kind==='withdrawals'?'down':'check')}</span><div><b>${esc(i.title)}</b><p>${esc(i.body)}</p><small>${date(i.created_at,true)} UTC</small></div></div>`).join(''):`<div class="notification-empty">${icon('bell')}<h3>Событий пока нет</h3><p>Новые сделки и сообщения появятся здесь.</p></div>`;return `<div class="notification-list">${body}</div>`;}
function updateNotificationBadge(){const button=$('#notifications');const unread=state.notifications?.unread||0;button.classList.toggle('has-unread',unread>0);button.setAttribute('aria-label',unread?`Уведомления: ${unread} новых`:'Уведомления');}
async function openNotifications(){state.notifications=await api('/notifications');updateNotificationBadge();const shown=state.notifications.items.filter(i=>!i.read_at).map(i=>i.id);await dialog('Уведомления',notificationPanel(),'Готово');if(!preview&&shown.length){state.notifications=await api('/notifications',{method:'POST',body:JSON.stringify({action:'read',ids:shown})});updateNotificationBadge();}}
async function addShortcut(){const help='<p>Откройте мини-приложение из чата с ботом в Telegram. Нажмите ⋮ справа сверху и выберите «Добавить на главный экран», если этот пункт есть на устройстве.</p><a class="text-link" href="https://t.me/tagmarketgold_bot" target="_blank" rel="noopener">Открыть бота в Telegram</a>';if(preview||!tg?.initData)return dialog('Ярлык Tag Markets',help,'Понятно');if(!tg?.addToHomeScreen)return dialog('Ярлык Tag Markets',help,'Понятно');try{if(tg.checkHomeScreenStatus)tg.checkHomeScreenStatus(s=>{if(s==='added')toast('Ярлык уже добавлен');else if(s==='unsupported')dialog('Ярлык Tag Markets',help,'Понятно');else tg.addToHomeScreen();});else tg.addToHomeScreen();}catch{return dialog('Ярлык Tag Markets',help,'Понятно');}}
function authScreen(){return `<main class="auth-screen"><div class="auth-glow"></div><div class="auth-brand"><div class="auth-mark"><svg viewBox="0 0 64 64" aria-hidden="true"><path class="logo-halo" d="M14.5 19a24 24 0 0 1 32-3M50.5 22a24 24 0 0 1-2 23M43 50.5a24 24 0 0 1-27-3"></path><path class="logo-letter" d="M20 22h24M32 22v22"></path><path class="logo-trend" d="m18 43 8-8 6 4 14-16"></path><circle class="logo-node" cx="46" cy="23" r="2.8"></circle><circle class="logo-seed" cx="18" cy="43" r="1.8"></circle></svg></div><span class="brand-wordmark"><strong>TAG</strong><small>MARKETS</small></span></div><span class="eyebrow">ЛИЧНЫЙ КАБИНЕТ · TELEGRAM MINI APP</span><h1>Ваш капитал<br><em>в одном ритме.</em></h1><p>Откройте приложение из чата с ботом, чтобы увидеть счета, сделки и гостей в защищённом личном пространстве.</p><a class="button primary auth-button" href="https://t.me/tagmarketgold_bot">Открыть бота в Telegram ${icon('arrow')}</a><small>Ссылка на приложение работает только внутри Telegram.</small></main>`;}
function accountBadge(a){return !a.enabled?'<span class="badge">На паузе</span>':a.status==='pending'?'<span class="badge warning">Ожидаем данные счёта</span>':'';}
function accountCard(a,i=0){const t=a.totals;const updated=a.synced?` title="Последние данные: ${esc(date(a.synced,true))} UTC"`:'';return `<a href="#account/${a.login}" class="panel account-card"${updated}><div class="strategy-icon ${i%2?'':'green'}">${icon('chart')}</div><div class="account-info"><h3>${esc(a.strategy||a.name)}</h3><p>${esc(a.holder||a.name)} · ${esc(a.login)}</p>${accountBadge(a)}</div><div class="account-money"><b>${t?money(t.now,t.cur):'—'}</b><p class="${signedClass(t?.month_pct)}">${t?`${t.month_pct>=0?'+':''}${number(t.month_pct)}% за месяц`:'Пока нет данных'}</p></div>${icon('chevron','chevron')}</a>`;}
function countLabel(n,forms){const v=Math.abs(Number(n))%100;const n10=v%10;return `${n} ${v>10&&v<20?forms[2]:n10===1?forms[0]:n10>=2&&n10<=4?forms[1]:forms[2]}`;}
function strategyFamily(a){const name=String(a.strategy||a.name||'').trim();return /sonic|sonik/i.test(name)?'SONIC':/neo/i.test(name)?'NEO':name;}
function sonicStrategyCard(compact=false){const account=state.data?.accounts.find(a=>!a.demo&&/sonic|sonik/i.test(`${a.strategy||''} ${a.name||''}`));return `<section class="panel strategy-card ${compact?'strategy-card-compact':''}"><div class="strategy-card-head"><div><span class="eyebrow">TAG MARKETS · НАША СТРАТЕГИЯ</span><h3>SONIC</h3></div><span class="strategy-chip">XAUUSD · золото</span></div><p class="strategy-lead">SONIC работает с движением цены золота. Алгоритм помогает находить моменты для входа, а трейдер контролирует сделки и риск.</p><div class="strategy-facts"><span><b>XAUUSD</b><small>инструмент</small></span><span><b>Алгоритм</b><small>поиск входа</small></span><span><b>Трейдер</b><small>контроль</small></span></div>${compact?`<p class="strategy-note">Ваш фактический результат всегда виден в отчёте по счёту.</p>${account?`<a class="text-link strategy-link" href="#account/${account.login}">Открыть SONIC ${icon('arrow')}</a>`:''}`:`<div class="strategy-extra"><span>Короткие сделки по золоту</span><span>Контроль риска на каждом входе</span><span>Прозрачная история операций в вашем кабинете</span></div><p class="strategy-note">Рынок меняется, поэтому результат стратегии зависит от сделок и не бывает фиксированным. Ваша доходность и история показаны ниже по этому счёту.</p>`}</section>`;}
function sonicGuide(){return `<section class="panel guide-card"><div class="guide-head"><div><span class="eyebrow">ПОДКЛЮЧЕНИЕ И ДОКУМЕНТЫ</span><h2>Перед подключением</h2></div><span class="badge">Памятка</span></div><div class="guide-grid"><div><b>1 · Регистрация</b><p>Создайте кабинет у брокера и подтвердите почту. Ссылку на регистрацию добавим здесь, когда она будет готова.</p></div><div><b>2 · Верификация</b><p>Подтвердите личность по инструкции в кабинете брокера. Пароли и коды подтверждения никому не отправляйте.</p></div><div><b>3 · Пополнение и подключение</b><p>Выберите удобный способ пополнения, затем подключите счёт к стратегии. Перед подтверждением проверьте сумму, комиссию и условия.</p></div><div><b>4 · Вывод средств</b><p>Оформляйте вывод в кабинете брокера. Проверьте доступную сеть, минимальную сумму, комиссию и адрес кошелька перед отправкой.</p></div></div><div class="license-note"><b>Лицензия брокера</b><p>Перед пополнением проверьте юридическое лицо, номер и действующий статус разрешения в официальном реестре регулятора. Реквизиты и условия брокера могут обновляться.</p></div></section>`;}
function chart(points,cur='USD',archived=false,scope='счёта'){if(!points?.length)return empty('Пока без сделок',`За выбранный период у ${scope} нет закрытых сделок.`);let total=0;const values=[0,...points.map(p=>total+=Number(p.value)||0)];const min=Math.min(...values),max=Math.max(...values),range=max-min||1;const coords=values.map((v,i)=>[i/(values.length-1)*640,140-(v-min)/range*120]);const d=coords.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 640 160" preserveAspectRatio="none" role="img" aria-label="Накопленный результат закрытых сделок: ${esc(money(total,cur))}"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b6da88" stop-opacity=".18"/><stop offset="100%" stop-color="#b6da88" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140].map(y=>`<path class="chart-grid" d="M0 ${y}H640"/>`).join('')}<path class="chart-area" d="${d} L640,160 L0,160Z"/><path class="chart-line" d="${d}"/><circle cx="640" cy="${coords.at(-1)[1]}" r="3" fill="var(--accent)" stroke="var(--panel)" stroke-width="2"/></svg></div><div class="chart-meta"><span>${archived?'Дат на графике':'Дней с результатом'} <b>${number(points.length)}</b></span><span>Пик <b>${money(max,cur,true)}</b></span><span>Итог <b class="${signedClass(total)}">${money(total,cur,true)}</b></span></div><div class="chart-labels"><span>${date(points[0].day)}</span><span>${archived?'Архив и сделки':'Закрытые сделки'} · ${esc(cur)}</span><span>${date(points.at(-1).day)}</span></div>`;}
function stats(items){return `<div class="stats ${items.length===2?'stats-two':''}">${items.map(([title,value,note,cls,ico])=>`<div class="panel stat"><div class="stat-title">${esc(title)}${icon(ico||'chart')}</div><div class="stat-value ${cls||''}">${value}</div><div class="stat-note">${esc(note)}</div></div>`).join('')}</div>`;}
function currentAccount(){return state.data.accounts.find(a=>String(a.login)===String(state.login))||state.data.accounts.find(a=>!a.demo&&a.enabled)||state.data.accounts[0];}
function periodTabs(){return `<div class="segmented">${periods.map(([key,label])=>`<button data-action="period" data-value="${key}" class="${state.period===key?'active':''}">${label}</button>`).join('')}</div>`;}
function customDates(){return state.period==='custom'?`<div class="custom-period"><div class="field-row"><label class="field">С даты<input type="date" id="from-date" value="${esc(state.from)}"></label><label class="field">По дату<input type="date" id="to-date" value="${esc(state.to)}"></label></div>${button('apply-period','Показать результат','secondary small')}</div>`:'';}
function onboardingCard(){const url=state.data?.onboarding?.registration_url;return `<section class="panel welcome-card onboarding-card"><div class="welcome-icon">${icon('arrow')}</div><span class="eyebrow">ПЕРВЫЙ ЗАПУСК</span><h2>Начните с регистрации</h2><p>Сначала создайте профиль в партнёрском портале, подтвердите почту и пройдите проверку. Затем зарегистрируйте Tag Markets через портал, получите данные счёта и подключите его здесь.</p><div class="onboarding-steps"><span><b>1</b> Профиль и почта</span><span><b>2</b> Верификация</span><span><b>3</b> Tag Markets и MT5</span></div>${url?`<a class="button primary" href="${esc(url)}" target="_blank" rel="noopener">Начать регистрацию ${icon('arrow')}</a>`:'<p class="muted">Ссылка регистрации пока не настроена владельцем.</p>'}<p class="stat-note">После подключения счёта эта памятка исчезнет, а на главной останутся брокер, стратегии и ваши результаты.</p></section>`;}
function overview(){const d=state.data, curr=state.currency||Object.keys(d.totals)[0]||'USD', t=d.totals[curr]||{capital:0,pnl:0,month:0}, own=d.accounts.filter(a=>!a.demo), visible=own.filter(a=>a.totals?.cur===curr), demo=d.accounts.find(a=>a.demo&&a.enabled), rep=state.report, strategies=new Set(own.filter(a=>a.enabled).map(strategyFamily)), cabinets=[...new Set(own.map(a=>a.cabinet||'Без номера'))];
 if(!own.length&&!demo)return header(`Добро пожаловать, ${d.user.name}`,'Личный кабинет для ваших счетов и результатов','')+onboardingCard();
  return header('Мой кабинет',`${d.user.name} · результат по всем добавленным счетам`,button('add','Добавить счёт','secondary','plus'))+
  `<div class="dashboard-grid"><div><section class="panel hero"><div class="hero-top"><span class="eyebrow">Мой капитал</span><span class="hero-pill">${esc(curr)}</span></div><div class="hero-value">${money(t.capital,curr)}</div><div class="hero-bottom"><div><p>Результат за всё время</p><b class="${t.pnl<0?'negative':''}">${money(t.pnl,curr,true)}</b></div><div class="separator"></div><div><p>Счетов в сводке</p><b>${number(visible.length)}</b></div></div></section>
 ${Object.keys(d.totals).length>1?`<div class="filterbar"><label class="field no-margin">Валюта сводки<select id="currency">${Object.keys(d.totals).map(c=>`<option ${curr===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div>`:''}
  ${stats([['Результат за месяц',money(t.month,curr,true),'После комиссии брокера',signedClass(t.month),'up'],['Аккаунты брокера',String(cabinets.length),`${countLabel(own.length,['торговый счёт','торговых счёта','торговых счетов'])} · ${countLabel(strategies.size,['стратегия','стратегии','стратегий'])}`,'','accounts']])}
  <section class="panel chart-panel"><div class="panel-head"><div><h2>Динамика результата</h2><p>Все добавленные счета · ${esc(curr)}</p></div>${periodTabs()}</div>${customDates()}${state.reportError?empty('Не удалось построить график',state.reportError):rep?`<div class="chart-summary"><strong class="${signedClass(rep.summary.net_income)}">${money(rep.summary.net_income,rep.currency,true)}</strong><span>${countLabel(rep.summary.count,['сделка','сделки','сделок'])} · ${countLabel(rep.accounts,['счёт','счёта','счетов'])}</span></div>${chart(rep.chart,rep.currency,rep.archived,'всех счетов')}`:empty(state.period==='custom'?'Выберите даты':'Загружаем результат',state.period==='custom'?'Укажите начало и конец периода прямо здесь.':'Рассчитываем данные по всем счетам.')}${rep?.archived?'<p class="stat-note">Старые месяцы показаны итогами, без отдельных сделок.</p>':''}</section>
  <div class="section-head"><h2>Мои счета <span class="muted">${own.length.toString().padStart(2,'0')}</span></h2><a href="#accounts" class="text-link">Управление ${icon('arrow')}</a></div>${own.length?`<div class="cabinet-list">${cabinets.map(c=>{const items=own.filter(a=>(a.cabinet||'Без номера')===c);return `<section class="cabinet-group"><div class="cabinet-group-head"><div><span class="eyebrow">МОЙ КАБИНЕТ</span><h3>${esc(c)}</h3></div><span class="badge">${countLabel(items.length,['счёт','счёта','счетов'])}</span></div><div class="account-list">${items.map(accountCard).join('')}</div></section>`;}).join('')}</div>`:empty('Начните со своего счёта','Подключите MT5 с инвесторским паролем. Приложение будет показывать сделки и результат.',button('add','Подключить счёт','primary','plus'))}</div>
 <aside class="side-stack">${sonicStrategyCard(true)}
 ${demo?`<section class="panel demo-panel"><span class="eyebrow">Публичная стратегия</span><h3>Наблюдайте за большим.</h3><p>Демо-счёт копитрейдинга. Реальные сделки, отдельная статистика.</p><div class="demo-number">${demo.totals?money(demo.totals.now,demo.totals.cur):'—'}</div><span class="badge demo">Не входит в ваш капитал</span><a class="button" href="#account/${demo.login}">Открыть демо ${icon('arrow')}</a></section>`:''}</aside></div>`;
}
function accountsView(){const items=state.data.accounts;const groups=[...new Set(items.filter(a=>!a.demo).map(a=>a.cabinet||'Без кабинета'))];return header('Ваши счета','Каждая стратегия — на своём месте.',button('add','Добавить счёт','primary','plus'))+groups.map(c=>`<div class="section-head"><h2>${esc(items.find(a=>(a.cabinet||'Без кабинета')===c)?.holder||c)}</h2><div class="inline-actions">${button('cabinet-report','Отчёт','secondary small','',`data-cabinet="${esc(c==='Без кабинета'?'—':c)}"`)}<span class="badge">${esc(c)}</span></div></div><div class="account-list">${items.filter(a=>!a.demo&&(a.cabinet||'Без кабинета')===c).map(accountCard).join('')}</div>`).join('')+(items.some(a=>a.demo)?`<div class="section-head"><h2>Демо-наблюдение</h2><span class="badge demo">Отдельно от личного капитала</span></div>${items.filter(a=>a.demo).map(accountCard).join('')}`:'')+(!items.length?empty('Ваш первый шаг','Подключите счёт и получите единую картину.',button('add','Подключить','primary','plus')):'');}
function tradesTable(rep){if(!rep?.deals?.length)return rep?.archived?empty('Сделки свёрнуты в итог месяца','Сумма и число сделок сохранены выше и в истории по месяцам. Детальные строки больше недоступны.'):empty('Нет операций за этот период','Попробуйте другой период. Данные появятся после синхронизации с MT5.');return `<div class="table-wrap"><table class="table trade-table"><thead><tr><th>Инструмент / сделка</th><th>Дата · UTC</th><th class="optional">Объём</th><th>Результат / %</th></tr></thead><tbody>${rep.deals.map(r=>`<tr><td><b>${esc(r.is_balance?(r.comment||'Балансовая операция'):r.symbol)}</b><span class="subline">${r.is_balance?'Движение средств':esc(r.side)} · #${esc(r.ticket)}${r.profit!=null?` · gross ${money(r.profit,rep.currency)}`:''}</span><span class="subline mobile-date">${date(r.time,true)} UTC</span></td><td>${date(r.time,true)}</td><td class="optional">${number(r.volume)} лот</td><td class="${signedClass(r.net_income)}"><b>${money(r.net_income,rep.currency,true)}</b>${r.pct_capital!=null?`<span class="trade-percent">${percent(r.pct_capital)} капитала</span>`:''}${r.commission||r.swap?`<span class="subline">комиссия ${money((Number(r.commission)||0)+(Number(r.swap)||0),rep.currency)}</span>`:''}</td></tr>`).join('')}</tbody></table></div><div class="inline-actions mt">${state.offset?button('prev','Назад','secondary small','back'):''}${rep.has_more?button('next','Следующие 50','secondary small','arrow'):''}</div>`;}
function reportFilters(){const acc=currentAccount();return `<section class="report-controls panel"><div class="report-control"><span class="eyebrow">СЧЁТ</span><label class="select-wrap"><select class="filter" id="account-select" aria-label="Выберите счёт">${state.data.accounts.map(a=>`<option value="${a.login}" ${a.login===acc?.login?'selected':''}>${esc(a.strategy||a.name)}${a.demo?' · общий просмотр':''}</option>`).join('')}</select>${icon('chevron')}</label><small>${esc(acc?.holder||'Выберите стратегию для просмотра истории')}</small></div><div class="report-control report-period"><span class="eyebrow">ПЕРИОД</span>${periodTabs()}</div></section>${customDates()}`;}
function dealsView(){const rep=state.report;return header('История в деталях','Сделки, движения средств и итоги по месяцам.')+reportFilters()+`<div class="filterbar"><div class="segmented">${[['trades','Сделки'],['moves','Движения'],['archive','По месяцам']].map(([key,label])=>`<button class="${state.kind===key?'active':''}" data-action="kind" data-value="${key}">${label}</button>`).join('')}</div></div>`+(state.reportError?empty('Не удалось открыть отчёт',state.reportError):!rep?empty(state.period==='custom'?'Выберите даты':'Загружаем сделки',state.period==='custom'?'Укажите период выше и нажмите «Показать результат».':'Получаем операции счёта.'):rep.pending?empty('Ожидаем данные','История этого счёта ещё не поступила.'):state.kind==='archive'?archive(rep):`<div class="panel">${rep.archived?notice('Часть истории свёрнута в месячные итоги. Детали прежних месяцев доступны во вкладке «По месяцам».'):''}${tradesTable(rep)}</div>`);}
function archive(rep){const max=Math.max(1,...rep.months.map(m=>Math.abs(m.net)));return `<section class="panel archive-panel"><div class="archive-head"><div><span class="eyebrow">ИСТОРИЯ</span><h2>Результат по месяцам</h2><p class="stat-note">После комиссии · по выбранному счёту</p></div><span class="badge">${rep.months.length} мес.</span></div><div class="archive-bars">${rep.months.map(m=>`<div class="archive-item"><div class="archive-month"><b>${esc(m.month)}</b><small class="${signedClass(m.net)}">${money(m.net,rep.currency,true)}</small></div><div class="archive-track ${m.net<0?'is-negative':''}"><progress value="${Math.abs(m.net)}" max="${max}" aria-label="Результат ${esc(m.month)}"></progress></div></div>`).join('')}</div>${!rep.months.length?empty('История ещё не накоплена','Месячные итоги появятся после первой синхронизации.'):''}</section>`;}
function accountView(){const a=currentAccount();if(!a)return empty('Счёт не найден','Возможно, владелец отозвал доступ.');const t=a.totals,rep=state.report;const sonic=(a.strategy||a.name||'').toLowerCase().includes('sonic')||(a.strategy||a.name||'').toLowerCase().includes('sonik');return `<a href="#accounts" class="text-link back">${icon('back')} Все счета</a>`+header(a.strategy||a.name,`${a.holder||a.name} · ${a.login} · ${a.server}`,button('account-settings','Настроить','secondary','settings',`data-login="${a.login}"`))+(a.demo?notice('Демо-наблюдение: этот капитал не входит в вашу личную сводку.'):a.shared?notice('Счёт предоставлен владельцем для наблюдения. Ваши уведомления настраиваются отдельно.'):'' )+(a.status==='pending'?notice('Счёт добавлен. Данные появятся после первого опроса.'):a.status==='stale'&&a.synced?`<p class="data-time">Последние данные · ${date(a.synced,true)} UTC</p>`:'')+(sonic?sonicStrategyCard(false):'')+stats([['Капитал',t?money(t.now,t.cur):'—','Реальные вложенные деньги','','accounts'],['Результат за всё время',t?money(t.pnl,t.cur,true):'—','После комиссии брокера',signedClass(t?.pnl),'up'],['Доходность',t?`${number(t.roi)}%`:'—','С учётом движения капитала',signedClass(t?.roi),'chart']])+reportFilters()+(rep&&!rep.pending?`<section class="panel chart-panel"><div class="panel-head"><h2>${esc(rep.title)}</h2><span class="badge">${rep.summary.count} сделок</span></div><div class="chart-summary"><strong class="${signedClass(rep.summary.net_income)}">${money(rep.summary.net_income,rep.currency,true)}</strong><span>чистый результат</span></div>${chart(rep.chart,rep.currency,rep.archived)}</section><div class="section-head"><h2>Последние сделки</h2>${button('full-report','Отчёт бота','secondary small')}</div><div class="panel">${tradesTable(rep)}</div><div class="section-head"><h2>История по месяцам</h2></div>${archive(rep)}`:'');}
function peopleView(){const p=state.people;return header('Ваш круг','Приглашения и доступ к вашим стратегиям.',button('invite','Пригласить','primary','plus'))+(!p?empty('Загружаем гостей','Это займёт несколько секунд.'): `<div class="section-head"><h2>Гости <span class="muted">${p.guests.length}</span></h2></div><div class="cards-grid">${p.guests.map(g=>`<section class="panel people-card"><div class="person-head"><div class="avatar">${esc(g.name.slice(0,1).toUpperCase())}</div><div><h3>${esc(g.name)}</h3><p>${esc(g.since||'Гость по приглашению')}</p></div></div><p>${countLabel(g.accounts.length,['доступный счёт','доступных счёта','доступных счетов'])}</p>${g.accounts.map(a=>`<div class="settings-row"><p>${esc(a.name)}</p>${button('take','Забрать','secondary small','',`data-guest="${g.id}" data-login="${a.login}"`)}</div>`).join('')}<div class="actions">${button('guest-detail','Подробнее','secondary small','',`data-guest="${g.id}"`)}${button('revoke-guest','Убрать доступ','danger small','',`data-guest="${g.id}"`)}</div></section>`).join('')}</div>${!p.guests.length?empty('Ваш круг пока пуст','Создайте приглашение и выберите счета, которыми хотите поделиться.'):''}<div class="section-head"><h2>Активные приглашения</h2><span class="badge">Одноразовые ссылки</span></div><div class="cards-grid">${p.invites.map(i=>`<section class="panel people-card"><h3>${i.logins.length?`${countLabel(i.logins.length,['счёт','счёта','счетов'])} для наблюдения`:'Без доступа к счетам'}</h3><p class="invite-url">${esc(i.url)}</p><div class="actions">${button('copy','Скопировать','secondary small','copy',`data-text="${esc(i.url)}"`)}${button('revoke-invite','Отозвать','danger small','',`data-token="${esc(i.token)}"`)}</div></section>`).join('')}</div>${!p.invites.length?'<p class="muted mt">Активных ссылок пока нет.</p>':''}`);}
function toggle(label,note,action,on,attrs=''){return `<div class="settings-row"><div><p>${esc(label)}</p><small>${esc(note)}</small></div><button class="switch" role="switch" aria-label="${esc(label)}" aria-checked="${!!on}" data-action="${action}" ${attrs}></button></div>`;}
function settingsView(){return header('Настройки','Оформление, уведомления и доступ.')+`<div class="two-column"><section class="panel"><h2>Личное пространство</h2>${toggle('Светлая тема','Оформление сохраняется на этом устройстве','theme',document.documentElement.dataset.theme==='light')}<button class="shortcut-hint" type="button" data-action="shortcut">${icon('plus')}<span><b>Добавить ярлык Tag Markets</b><small>Открывайте кабинет с главного экрана телефона.</small></span>${icon('chevron')}</button></section><section class="panel"><h2>Счета и уведомления</h2>${state.data.accounts.map(a=>`<div class="settings-row"><div><p>${esc(a.name)}</p><small>${a.enabled?'Отслеживание включено':'Скрыт / отслеживание выключено'}</small></div>${button('account-settings','Настроить','secondary small','',`data-login="${a.login}"`)}</div>`).join('')||'<p class="muted mt">Сначала подключите счёт.</p>'}</section></div>${sonicGuide()}${state.data.founder?`<div class="section-head"><h2>Управление сервисом</h2></div><section class="panel">${toggle('Служебные уведомления','Состояние машин и обновления','alerts',state.data.update_alerts)}<div class="settings-row"><div><p>Сообщение пользователям</p><small>Текст и получатели проверяются перед отправкой</small></div>${button('broadcast','Написать','secondary small')}</div>${state.admin?.machines.map(m=>`<div class="settings-row"><div><p>${esc(m.host)}</p><small>${esc(m.role)} · ${m.seen?date(m.seen,true):'—'} UTC</small></div><span class="badge">${m.host===state.admin.active?'Опрашивает':'Резерв'}</span></div>`).join('')||''}</section>`:`<div class="mt">${button('leave','Отключить мой доступ','danger')}</div>`}`;}
function render(){nav();const views={overview,accounts:accountsView,deals:dealsView,account:accountView,people:peopleView,settings:settingsView};$('#main').innerHTML=(preview?'<div class="preview-label">Демо-режим · вымышленные данные. Отправка сообщений и управление счетами работают только при запуске из <a href="https://t.me/tagmarketgold_bot" target="_blank" rel="noopener">бота в Telegram</a>.</div>':'')+(views[state.view]||overview)()+(state.view==='settings'&&state.admin?.network?.length?networkView():'');$('#avatar').textContent=state.data.user.name.slice(0,1).toUpperCase();document.querySelectorAll('.segmented').forEach(strip=>{const active=strip.querySelector('.active');if(active)strip.scrollLeft+=active.getBoundingClientRect().left-strip.getBoundingClientRect().left-(strip.clientWidth-active.clientWidth)/2;});}
async function api(path,options={}){if(preview){if(path==='/notifications')return {items:[{id:1,kind:'trades',title:'SONIC · новая сделка',body:'XAUUSD · результат +18,42 $',created_at:new Date().toISOString(),read_at:null}],unread:1};if(options.method&&options.method!=='GET')throw new Error('В предпросмотре изменения отключены');const d=await fetch('preview.json',{cache:'no-store'}).then(r=>r.json());if(path==='/bootstrap')return d.bootstrap;if(path==='/people')return d.people;if(path==='/admin')return d.admin;if(path.startsWith('/guests/'))return {report:'Виктория Орлова\n\nСчета гостя\n• SONIC 2 · 2 840,00 $\n\nЗаработок без демо-счёта\nСегодня  +42,18 $\nНеделя   +186,40 $\nМесяц    +312,66 $\n\nДемо-счёт в расчёт не входит.'};if(path.startsWith('/cabinets/'))return {report:'Отчёт кабинета · CU-1\n\nЛичные стратегии: 2\nРезультат после комиссии: +684,32 $\nДемо-счёт исключён из итога.'};if(path.startsWith('/overview/report'))return structuredClone(d.overview_report);if(path.includes('/report')){const r=structuredClone(d.report);if(new URLSearchParams(path.split('?')[1]).get('kind')==='moves')r.deals=[];return r;}throw new Error('Этот раздел недоступен в предпросмотре');}const isForm=options.body instanceof FormData;const headers={'X-Telegram-Init-Data':tg?.initData||'',...options.headers};if(!isForm&&!headers['Content-Type'])headers['Content-Type']='application/json';const response=await fetch(new URL('../api'+path,location.href),{...options,signal:AbortSignal.timeout(path==='/broadcast'?180000:20000),headers,cache:'no-store'});const d=await response.json().catch(()=>({error:'Сервер вернул некорректный ответ'}));if(!response.ok)throw new Error(d.error||`Ошибка ${response.status}`);return d;}
async function loadReport(){const params=new URLSearchParams({period:state.period});if(state.period==='custom'){if(!state.from||!state.to)return null;params.set('from',state.from);params.set('to',state.to);}if(state.view==='overview'){params.set('currency',state.currency||Object.keys(state.data.totals)[0]||'USD');return api(`/overview/report?${params}`);}const acc=currentAccount();if(!acc)return null;state.login=acc.login;params.set('kind',state.kind);params.set('offset',state.offset);return api(`/accounts/${acc.login}/report?${params}`);}
async function refresh(quiet=false){
 if(state.busy){if(!quiet){state.pendingRefresh=true;generation++;}return;}
 state.busy=true;const gen=++generation;
 try{
  const data=await api('/bootstrap');if(gen!==generation)return;state.data=data;
  let report,people,admin;
   if(['overview','account','deals'].includes(state.view)){try{report=await loadReport();state.reportError='';state.report=report;}catch(error){state.report=null;state.reportError=error.message;}}
  if(state.view==='people')people=await api('/people');
  if(state.view==='settings'&&data.founder)admin=await api('/admin');
  const notifications=await api('/notifications').catch(()=>state.notifications);
  if(gen!==generation)return;
   if(people)state.people=people;if(admin)state.admin=admin;
  state.notifications=notifications;updateNotificationBadge();
  const newest=notifications.items?.[0];
  if(newest&&notifications.unread&&(!notificationsStarted||newest.id>lastNotificationId))
   toast(notifications.unread===1?`Новое событие · ${newest.title}`:`${notifications.unread} новых событий · ${newest.title}`);
  notificationsStarted=true;lastNotificationId=Math.max(lastNotificationId,newest?.id||0);
  if(!quiet||!document.querySelector('input:focus,textarea:focus,select:focus'))render();
 }catch(error){
  if(!state.data){if(!preview&&!tg?.initData){$('#main').innerHTML=authScreen();}else $('#main').innerHTML=empty('Не удалось открыть кабинет',error.message,button('refresh','Попробовать снова','primary','refresh'));}
  else if(!quiet)toast('Не удалось обновить данные. Показаны последние полученные значения.');
 }finally{state.busy=false;if(state.pendingRefresh){state.pendingRefresh=false;await refresh();}}
}
async function navigate(){const [view,login]=location.hash.slice(1).split('/');state.view=['overview','accounts','deals','account','people','settings'].includes(view)?view:'overview';if(login)state.login=Number(login);state.offset=0;state.kind='trades';state.report=null;state.reportError='';nav();if(state.data){render();}await refresh();tg?.BackButton?.[state.view==='account'?'show':'hide']();}
function setTheme(theme,persist=true){document.documentElement.dataset.theme=theme;try{if(persist)localStorage.setItem('tag-theme',theme);}catch{}const color=theme==='light'?'#f4f5f0':'#111416';document.querySelector('meta[name="theme-color"]').content=color;try{tg?.setHeaderColor(color);tg?.setBackgroundColor(color);}catch{}if(state.data&&state.view==='settings')render();}
function switchTheme(){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');}
function dialog(title,body,label='Сохранить'){return new Promise(resolve=>{const d=$('#dialog');$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog-submit').textContent=label;d.returnValue='';d.onclose=()=>{const values=Object.fromEntries(new FormData($('form',d)));resolve(d.returnValue==='confirm'?values:null);};$('form',d).onsubmit=e=>{if(e.submitter?.value==='cancel')return;const fields=[...d.querySelectorAll('input,select,textarea')];if(!fields.every(f=>f.reportValidity()))e.preventDefault();};d.showModal();});}
async function confirm(title,text,label='Подтвердить'){return !!await dialog(title,`<p>${esc(text)}</p>`,label);}
async function mutate(path,data,method='POST'){await api(path,{method,body:data===undefined?undefined:JSON.stringify(data)});tg?.HapticFeedback?.notificationOccurred('success');toast('Сохранено. Изменения доступны и в боте.');await refresh();}
function field(label,name,type='text',value='',extra=''){return `<label class="field">${esc(label)}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
async function configureAccount(login){const a=state.data.accounts.find(a=>a.login===Number(login));if(!a)return;const body=`${a.demo?notice('Демо-счёт: только отображение и уведомления.'):field('Название стратегии','name','text',a.strategy||a.name,'required maxlength="48"')}<label class="check"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}>${a.demo?'Показывать демо-счёт':'Отслеживать счёт'}</label>${[['all','Все уведомления'],['trades','Сделки'],['deposits','Пополнения'],['withdrawals','Выводы']].map(([k,v])=>`<label class="check"><input type="checkbox" name="${k}" ${a.notify?.[k]!==false?'checked':''}>${v}</label>`).join('')}${!a.demo&&!a.shared?field('Привязать капитал Invested (необязательно)','base','number','','min="0" max="1000000000000" step="0.01"')+'<p>Заполняйте только для корректировки капитала на текущую дату.</p>':''}${!a.demo?`<div class="inline-actions mt">${button('delete-account','Удалить из приложения','danger small','',`data-login="${a.login}"`)}${!a.shared?button('restart','Перезапустить терминал','secondary small','',`data-login="${a.login}"`):''}</div>`:''}`;const values=await dialog('Настройки счёта',body);if(!values)return;const data={enabled:values.enabled==='on',notify:Object.fromEntries(['all','trades','deposits','withdrawals'].map(k=>[k,values[k]==='on']))};if(values.name)data.name=values.name;if(values.base!=='')if(values.base!==undefined)data.base=Number(values.base);await mutate(`/accounts/${a.login}`,data,'PATCH');}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const action=el.dataset.action;if(el.disabled)return;el.disabled=true;try{
 if(action==='refresh')await refresh();
 else if(action==='notifications')await openNotifications();
 else if(action==='shortcut')await addShortcut();
 else if(action==='theme')switchTheme();
 else if(action==='period'){state.period=el.dataset.value;state.offset=0;state.report=null;state.reportError='';if(state.period==='custom')render();else await refresh();}
 else if(action==='kind'){state.kind=el.dataset.value;state.offset=0;await refresh();}
 else if(action==='next'||action==='prev'){state.offset=Math.max(0,state.offset+(action==='next'?50:-50));await refresh();}
 else if(action==='apply-period'){state.from=$('#from-date').value;state.to=$('#to-date').value;if(!state.from||!state.to||state.from>state.to)throw new Error('Укажите корректные даты начала и конца');await refresh();}
 else if(action==='add'){const d=await dialog('Подключить счёт MT5',`<p>Используйте инвесторский пароль: он даёт доступ только к просмотру.</p>${field('Название стратегии','name','text','','required maxlength="48" placeholder="Например, SONIC или NEO"')}${field('Номер счёта MT5','login','number','','required min="1" step="1" placeholder="Например, 10001234"')}${field('Инвесторский пароль','password','password','','required maxlength="128" autocomplete="new-password" placeholder="Пароль инвестора MT5"')}<div class="field-row">${field('Кабинет (CU…)','cabinet','text','','maxlength="32" placeholder="Например, CU228816"')}<div class="auto-field"><span>Сервер и владелец</span><b>Определятся автоматически</b><small>После первой синхронизации из терминала MT5</small></div></div>`,'Подключить');if(d){await mutate('/accounts',d);location.hash='accounts';}}
 else if(action==='account-settings')await configureAccount(el.dataset.login);
 else if(action==='delete-account'){if($('#dialog').open)$('#dialog').close('cancel');if(await confirm('Удалить счёт?','Он исчезнет из вашего приложения и бота. Торговый счёт у брокера останется.','Удалить')){await mutate(`/accounts/${el.dataset.login}`,undefined,'DELETE');location.hash='accounts';}}
 else if(action==='restart'){if($('#dialog').open)$('#dialog').close('cancel');if(await confirm('Перезапустить терминал?','Это общий терминал агента. Опрос остальных счетов кратковременно прервётся.','Перезапустить'))await mutate('/actions',{action:'restart',login:Number(el.dataset.login)});}
 else if(action==='full-report'){await dialog('Отчёт Telegram-бота',`<div class="report-text">${esc(state.report.report)}</div>`,'Готово');}
 else if(action==='invite'){const own=state.data.accounts.filter(a=>!a.demo&&!a.shared);const d=await dialog('Приглашение в ваш круг',`<p>Ссылка одноразовая. Отметьте счета для просмотра или оставьте приглашение без счетов.</p>${own.map(a=>`<label class="check"><input name="login-${a.login}" type="checkbox">${esc(a.name)}</label>`).join('')}`,'Создать ссылку');if(d){const result=await api('/invites',{method:'POST',body:JSON.stringify({logins:Object.keys(d).filter(k=>k.startsWith('login-')).map(k=>Number(k.slice(6)))})});await refresh();await dialog('Приглашение готово',`<p class="invite-url">${esc(result.url)}</p>${button('copy','Скопировать','secondary','copy',`data-text="${esc(result.url)}"`)}`,'Готово');}}
 else if(action==='copy'){try{await navigator.clipboard.writeText(el.dataset.text);toast('Ссылка скопирована');}catch{throw new Error('Не удалось скопировать автоматически. Выделите и скопируйте ссылку.');}}
 else if(action==='revoke-invite'){if(await confirm('Отозвать приглашение?','Ссылка больше не будет предоставлять доступ.'))await mutate('/invites/'+el.dataset.token,undefined,'DELETE');}
 else if(action==='cabinet-report'){const r=await api('/cabinets/'+encodeURIComponent(el.dataset.cabinet)+'/report?period='+(state.period==='custom'?'month':state.period));await dialog('Отчёт кабинета',`<div class="report-text">${esc(r.report)}</div>`,'Готово');}
 else if(action==='guest-detail'){const r=await api('/guests/'+el.dataset.guest);await dialog('Карточка гостя',`<div class="report-text">${esc(r.report)}</div>`,'Готово');}
 else if(action==='revoke-guest'){if(await confirm('Закрыть доступ гостю?','Ваши переданные счета исчезнут у гостя. Его личные счета и доступ к собственному кабинету сохранятся.','Закрыть доступ'))await mutate('/guests/'+el.dataset.guest,{action:'revoke'});}
 else if(action==='take'){if(await confirm('Забрать счёт у гостя?','Остальные счета гостя сохранятся.'))await mutate('/guests/'+el.dataset.guest,{action:'take',login:Number(el.dataset.login)});}
 else if(action==='alerts')await mutate('/actions',{action:'update_alerts',value:!state.data.update_alerts});
 else if(action==='leave'){if(await confirm('Отключить доступ?','Счета и приглашения в боте будут удалены. Для возвращения понадобится новое приглашение.','Отключить')){await api('/actions',{method:'POST',body:JSON.stringify({action:'leave'})});state.data=null;await refresh();}}
 else if(action==='broadcast'){
  const users=state.admin?.users||[];
  if(!users.length)throw new Error('Пока нет приглашённых пользователей для рассылки');
  const d=await dialog('Сообщение пользователям',`<label class="field">Получатели<select name="target"><option value="all">Все приглашённые · ${users.length}</option>${users.map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('')}</select></label><div class="compose-tools"><button type="button" class="format-btn" data-format="bold" aria-label="Жирный"><b>Ж</b></button><button type="button" class="format-btn" data-format="italic" aria-label="Курсив"><i>К</i></button><button type="button" class="format-btn" data-format="mono" aria-label="Моноширинный"><code>М</code></button><button type="button" class="format-btn" data-format="quote" aria-label="Цитата">❝</button><span>Форматирование</span></div><label class="field"><span>Текст сообщения</span><textarea name="text" maxlength="4096" placeholder="Напишите обновление для пользователей…"></textarea><small>Выделите фрагмент и нажмите кнопку формата.</small></label><label class="field">Фото или видео<input type="file" name="media" accept="image/jpeg,image/png,video/mp4"><small>JPG/PNG до 10 МБ · MP4 до 20 МБ</small></label>`,'Проверить');
  if(!d)return;
  const file=d.media?.size?d.media:null;
  if(!String(d.text||'').trim()&&!file)throw new Error('Добавьте текст или файл');
  if(file&&!['image/jpeg','image/png','video/mp4'].includes(file.type))throw new Error('Выберите JPG, PNG или MP4');
  if(file&&file.size>(file.type==='video/mp4'?20:10)*1024*1024)throw new Error('Фото до 10 МБ, видео до 20 МБ');
  const recipient=d.target==='all'?`все приглашённые (${users.length})`:users.find(u=>String(u.id)===String(d.target))?.name||'пользователь';
  const objectUrl=file?URL.createObjectURL(file):null;
  try{
   const media=file?`<div class="compose-preview-media">${file.type.startsWith('image/')?`<img src="${esc(objectUrl)}" alt="Приложенное фото">`:`<video src="${esc(objectUrl)}" controls preload="metadata"></video>`}<small>${esc(file.name)} · ${fileSize(file.size)}</small></div>`:'';
   const body=`<p class="compose-recipient">Кому: <b>${esc(recipient)}</b></p>${media}<div class="compose-preview-text">${d.text?broadcastPreview(d.text):'<span class="muted">Без подписи</span>'}</div><p class="compose-footnote">Проверьте сообщение перед отправкой.</p>`;
   if(!await dialog('Проверка рассылки',body,'Отправить'))return;
  }finally{if(objectUrl)URL.revokeObjectURL(objectUrl);}
  if(preview){await dialog('Демо-режим',`<p>Макет показывает редактор и вложение, но не отправляет сообщения. Для настоящей рассылки откройте приложение из <a href="https://t.me/tagmarketgold_bot" target="_blank" rel="noopener">бота в Telegram</a>.</p>`,'Понятно');return;}
  const form=new FormData();form.append('target',d.target);form.append('text',d.text||'');form.append('request_id',crypto.randomUUID());if(file)form.append('media',file);
  const result=await api('/broadcast',{method:'POST',body:form});toast(`Отправлено: ${result.sent}. Не доставлено: ${result.failed}.`);
 }
 }catch(error){toast(error.message);}finally{el.disabled=false;}});
document.addEventListener('click',event=>{const tool=event.target.closest('[data-format]');if(!tool)return;event.preventDefault();const area=$('#dialog textarea[name="text"]');if(!area)return;const start=area.selectionStart,end=area.selectionEnd,selected=area.value.slice(start,end);const tags={bold:['<b>','</b>'],italic:['<i>','</i>'],mono:['<code>','</code>'],quote:['<blockquote>','</blockquote>']}[tool.dataset.format];if(!tags)return;area.setRangeText(tags[0]+selected+tags[1],start,end,'end');area.focus();area.setSelectionRange(start+tags[0].length,start+tags[0].length+selected.length);});
 document.addEventListener('change',async event=>{try{if(event.target.id==='account-select'){state.login=Number(event.target.value);state.offset=0;if(state.view==='account'){location.hash='account/'+state.login;}else await refresh();}if(event.target.id==='currency'){state.currency=event.target.value;state.report=null;await refresh();}}catch(error){toast(error.message);}});
$('#notifications').innerHTML=icon('bell');$('#refresh').innerHTML=icon('refresh');$('#refresh').addEventListener('click',()=>refresh());$('#theme').innerHTML=icon('sun');$('#theme').addEventListener('click',switchTheme);
