 const originalSettingsView=settingsView;settingsView=function(){const url=state.data?.onboarding?.partner_url||'';return originalSettingsView()+`<section class="panel partner-link-panel"><div class="settings-row"><div><p>Партнёрская ссылка</p><small>${url?'Сохранена для будущих приглашений':'Добавьте персональную ссылку из IB Portal → Partner'}</small></div>${button('partner-link',url?'Изменить':'Добавить','secondary small')}</div></section>`;};
 navigate();refreshTimer=setInterval(()=>{if(!document.hidden&&!$('#dialog').open&&state.period!=='custom')refresh(true);},15000);

function networkView(){return `<div class="section-head"><h2>Доход партнёрской сети</h2></div><section class="panel"><p class="stat-note">По событиям портала · последние 30 дней с начислениями · валюта портала</p><div class="table-wrap"><table class="table"><thead><tr><th>Дата</th><th>Сделок сети</th><th>Начислено</th></tr></thead><tbody>${state.admin.network.map(d=>`<tr><td>${esc(d.day)}</td><td>${number(d.trades)}</td><td class="positive">${number(d.income)}</td></tr>`).join('')}</tbody></table></div></section>`;}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action="partner-link"]');if(!el)return;event.preventDefault();const current=state.data?.onboarding?.partner_url||'';const body=`<p>Откройте <a href="https://exfusion.ibportal.io" target="_blank" rel="noopener">IB Portal</a>, внизу справа откройте блок <b>Partner</b>, скопируйте свою персональную ссылку и вставьте её сюда.</p><label class="field">Партнёрская ссылка<input name="url" type="url" value="${esc(current)}" required placeholder="https://exfusion.ibportal.io/auth/register?..." /></label>`;const values=await dialog('Моя партнёрская ссылка',body,'Сохранить');if(!values)return;try{const saved=await api('/profile/partner-link',{method:'PUT',body:JSON.stringify({url:values.url})});state.data.onboarding.partner_url=saved.url;toast('Партнёрская ссылка сохранена');render();}catch(error){toast('Ссылка не принята: проверьте адрес из блока Partner.');}});

